DROP TABLE IF EXISTS `payment_channel_statement`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payment_channel_statement` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `community_id` bigint NOT NULL,
  `provider` varchar(32) NOT NULL,
  `statement_date` date NOT NULL,
  `trade_type` varchar(32) NOT NULL,
  `bill_id` bigint NOT NULL,
  `order_no` varchar(96) NOT NULL,
  `channel_trade_no` varchar(128) NOT NULL,
  `amount` decimal(14,2) NOT NULL,
  `status` varchar(32) NOT NULL,
  `synced_at` datetime NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `provider` (`provider`,`statement_date`,`trade_type`,`channel_trade_no`),
  KEY `idx_payment_statement_community` (`community_id`,`provider`,`statement_date`)
) ENGINE=InnoDB AUTO_INCREMENT=73 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
