  `tax_invoice_no` varchar(80) DEFAULT NULL,
  `tax_platform_code` varchar(80) DEFAULT NULL,
  `pdf_url` varchar(300) DEFAULT NULL,
  `checksum` varchar(128) DEFAULT NULL,
  `fail_reason` varchar(300) DEFAULT NULL,
  `issued_by` varchar(64) NOT NULL,
  `issued_at` datetime DEFAULT NULL,
  `red_original_id` bigint DEFAULT NULL,
  `red_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `invoice_request_no` (`invoice_request_no`),
